package com.fasterxml.jackson.dataformat.xml.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.PackageVersion;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Set;
import javax.xml.stream.XMLStreamReader;
import javax.xml.stream.XMLStreamWriter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FromXmlParser.nextTextValue().
 * Note: The provided code contains an 'if (true)' block which makes the subsequent 
 * XML parsing logic unreachable in the current implementation. 
 * These tests target the reachable logic (the 'if (true)' branch).
 */
public class FromXmlParser_nextTextValue_TriageGen2Test {

    private FromXmlParser parser;

    @Mock
    private IOContext ioContext;
    @Mock
    private ObjectCodec codec;
    @Mock
    private XMLStreamReader xmlReader;

    @Mock
    private JsonToken mockToken;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        parser = new FromXmlParser(ioContext, 0, 0, codec, xmlReader);

        // Use reflection to inject the _nextToken field since it is private/protected
        setInternalState(parser, "_nextToken", mockToken);
    }

    /**
     * Tests the case where the current token is VALUE_STRING.
     * This covers the primary "expected case" in the 'if (true)' block.
     */
    @Test
    public void testNextTextValue_WhenTokenIsValueString() throws Exception {
        // Arrange
        setInternalState(parser, "_currText", "expectedValue");
        setInternalState(parser, "_nextToken", JsonToken.VALUE_STRING);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("expectedValue", result);
        // Verify that _currToken was updated to the token that was in _nextToken
        assertEquals(JsonToken.VALUE_STRING, getInternalState(parser, "_currToken"));
        // Verify that _nextToken was nulled out
        assertNull(getInternalState(parser, "_nextToken"));
    }

    /**
     * Tests the case where the token is NOT a VALUE_STRING.
     * This covers the branch where _updateState(t) is called and null is returned.
     */
    @Test
    public void testNextTextValue_WhenTokenIsNotValueString() throws Exception {
        // Arrange
        setInternalState(parser, "_nextToken", JsonToken.START_OBJECT);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.START_OBJECT, getInternalState(parser, "_currToken"));
        assertNull(getInternalState(parser, "_nextToken"));
    }

    /**
     * Tests that _binaryValue is reset to null at the beginning of the method.
     */
    @Test
    public void testNextTextValue_ResetsBinaryValue() throws Exception {
        // Arrange
        byte[] dummyData = new byte[]{1, 2, 3};
        setInternalState(parser, "_binaryValue", dummyData);
        setInternalState(parser, "_nextToken", JsonToken.VALUE_STRING);
        setInternalState(parser, "_currText", "val");

        // Act
        parser.nextTextValue();

        // Assert
        assertNull(getInternalState(parser, "_binaryValue"));
    }

    // --- Helper methods for reflection to access private fields ---

    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Object getInternalState(Object target, String fieldName) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        try {
            return clazz.getDeclaredField(fieldName);
        } catch (NoSuchFieldException e) {
            Class<?> superClass = clazz.getSuperclass();
            if (superClass != null) {
                return findField(superClass, fieldName);
            }
            throw e;
        }
    }
}
